proof297=[
dict(id='B1',statement='A bounded continuous convex perturbation on an unbalanced rational orthant can fail ALL finite REAL-PA uniform density.',proof='Let sigma=R_+^2, gamma(x,y)=x+y and b(x,y)=max(0,1-sqrt(xy)). Let f=gamma+b. The geometric mean sqrt(xy) is concave on the positive orthant: its second directional derivative is -(y dx-x dy)^2/(4(xy)^(3/2))<=0. Continuity extends concavity to the closed orthant; equivalently use the two-variable Cauchy-Schwarz inequality. Thus1-sqrt(xy) is convex and its maximum with0 is convex. The function b is continuous, 0<=b<=1, and f is finite continuous convex boundedly relative to the literal reference gamma. Gamma is positive in every nonzero orthant recession direction. For any fixed base point in sigma and recession v, b is bounded, so f has EXACT recession gamma(v). No irrational spatial PA wall is presumed: f is a continuous NON-PA endpoint.'),
dict(id='B2',statement='Every finite continuous REAL-PA approximant has uniform error at least1/2.',proof='Any finite continuous PA function a on the convex orthant is globally Lipschitz: finitely many affine gradients have a finite largest Euclidean norm, and a line segment splits into finitely many affine subsegments; summing their bounds proves one global constant. The same applies to a-gamma, with any real coefficients and any finite carrier; rational geometry is not needed for this obstruction. At z_n=(n^2,0), b(z_n)=1. At w_n=(n^2,n^-2), b(w_n)=0 because their coordinate product is1. Their Euclidean distance is n^-2. If e=||a-f||_infinity is finite and L is the global Lipschitz constant of a-gamma, then1=|b(z_n)-b(w_n)|<=2e+L n^-2. Let n tend to infinity to get e>=1/2. Therefore no uniform finite REAL-PA approximation exists, and hence no global decreasing-uniform such approximation. This is a continuum error floor against EVERY finite PA function, not a sampled-grid failure. The endpoint is not even uniformly continuous relative to gamma.'),
dict(id='B3',statement='Why this does not close or refute the original balanced-space problem.',proof='The positive-dimensional orthant with its single usual top weight is NOT balanced along its boundary rays. Thus (sigma,gamma) does not satisfy original P05.1 ambient balance, and this is NOT an original counterexample or a regularity classification. The example diagnoses why C3 of working296 cannot drop its global Lipschitz hypothesis merely from boundedness and cellwise convexity. It also cannot be glued into a continuous convex full-plane endpoint across y=0: for any fixed x>0, the inward difference quotient of b in y tends to -infinity. A finite convex function on an open neighborhood of (x,0) is locally Lipschitz (vertex upper bound, reflection lower bound and secants), so its restriction cannot have that quotient. Balance and all legal cross-face PCCs may rule out this boundary pathology; that implication and uniform estimates on arbitrary finite supports still need complete proofs. No MA is assigned to the failed approximant domain and no raw contact assertion follows.')]
write('P05.1-continuation297-unbalanced-orthant-continuous-convex-real-PA-error-floor-boundary-diagnostic-working-proof-20261008.json',dict(recorded_utc=now,continuation=297,atom='P05.1',status='UNREVIEWED complete diagnostic, NOT an original balanced counterexample',proof_units=proof297,exact_uniform_error_floor='1/2',actual_reference='gamma=x+y on R_+^2, literal and positive on its nonzero recession',balance_hypothesis_fails=True,not_supplied_to_active220221=True,no_hot_feedback=True,new_mathematical_grant=False,new_accepted_paper=False,original_closed=False,no_MA_assigned=True,ordinary_foundations='Elementary calculus/Cauchy-Schwarz, finite affine segment subdivision and real limits; no external research theorem.'))
